data=[]
arabic={12:'جبل ثاة',16:'منتزة المسقي',21:'منتجع ومزرعة التوت الأسود',23:'وسمره صيف',25:'مسجد وقرية المخض الاثرية',30:'قرية ال ينفع تمنية'}
prices={5:{'amount':25,'currency':'SAR','unit':'per person'},13:{'amount':20,'currency':'SAR','unit':'per person'},21:{'amount':15,'currency':'SAR','unit':'per person, afternoon','note':'The reference lists free morning entry.'},27:{'amount':30,'currency':'SAR','unit':'per person'}}
for i,(slug,name,category,page,indices,location,short,description,highlights) in enumerate(rows,1):
    gallery=[]
    for j,index in enumerate(indices):
        file=f'page-{page:02d}-{index:02d}.jpg'
        image=Image.open(source/file).convert('RGB')
        if page==30 and index in [2,6]: image=image.rotate(90,expand=True)
        basename=slug if j==0 else f'{slug}-{j+1}'
        image.save(output/f'{basename}.webp',quality=88,method=6)
        for width in [320,480,640,960,1280,1920]:
            # Never invent image detail by enlarging compressed source photography.
            w=min(image.width,width)
            resized=image.resize((w,round(image.height*w/image.width)),Image.Resampling.LANCZOS)
            resized.save(output/f'{basename}-{width}.webp',quality=86,method=6)
        gallery.append({'src':f'/images/destinations/{basename}.webp','alt':f'{name} — photograph {j+1} from Aseer Explore','width':image.width,'height':image.height})
    links=[x for x in records[page-1]['links'] if x.startswith('https://maps.app.goo.gl/')]
    link=links[1] if i==11 and len(links)>1 else (links[0] if links else None)
    tags=[category]+({'Nature':['Family','Relaxation'],'Farms':['Nature','Family','Relaxation'],'Parks':['Nature','Family','Relaxation'],'Mountains':['Nature','Adventure','Scenic Views'],'Heritage':['Family'],'Dams':['Nature','Relaxation'],'Scenic Views':['Nature','Relaxation'],'Waterfalls':['Nature','Adventure'],'Activities':['Family'],'Adventure':['Nature','Mountains','Waterfalls'],'Family':['Activities']}[category])
    item={'id':f'{i:02d}','slug':slug,'name':name,'category':category,'shortDescription':short,'description':description,'location':location or None,'image':gallery[0]['src'] if gallery else None,'gallery':gallery,'featured':i in [1,2,3,7,29],'mapUrl':link,'tags':tags,'highlights':highlights.split('|'),'sourcePage':page}
    if i in arabic: item['arabicName']=arabic[i]
    if i in prices:item['ticketPrice']=prices[i]
    data.append(item)
(root/'data').mkdir(exist_ok=True)
(root/'data/destinations.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
print(f'Prepared {len(data)} destinations and {sum(len(x["gallery"]) for x in data)} source photos')


